def match(self, task_description: str, min_success_rate: float = 0.6) -> dict | None:
        """Token-overlap match; the best procedure above the success floor wins."""
        toks = set(task_description.lower().split())
        best, best_score = None, 0.0
        for proc in self.procedures.values():
            if proc.get("success_rate", 0.0) < min_success_rate:
                continue
            ptoks = set(proc["trigger_pattern"].split())
            if not ptoks:
                continue
            score = len(toks & ptoks) / len(toks | ptoks)
            if score > best_score:
                best, best_score = proc, score
        return best

