def _process_lineage() -> set:
    """This pid and every parent above it."""
    pids = set()
    try:
        import psutil
        cur = psutil.Process()
        for _ in range(24):
            pids.add(cur.pid)
            parent = cur.parent()
            if parent is None or parent.pid in pids:
                break
            cur = parent
    except Exception:
        pids.add(os.getpid())
    return pids

