def _patch_runner(self, plan, test_cmd):
        """Absolute runner path: the terminal's cwd is not our sandbox."""
        if not test_cmd:
            return
        runner = str(Path(self.filesystem.root) / "_rt_check.py")
        runner = runner.replace("\\", "/")
        for s in plan:
            if s["action"] == "TEST" and isinstance(s["content"], dict) \
                    and s["content"].get("cmd") == test_cmd:
                s["content"]["cmd"] = f'python "{runner}"'

def decay(self, rate: float = 0.05):
        """Attention-like forgetting: untouched thoughts fade; below 0.1
        they drop out of mind entirely (goal-class priorities survive -
        only ACCESS refreshes, never priority inflation)."""
        gone = []
        for k, s in self.slots.items():
            s["priority"] -= rate * max(0, 1.0 - 0.25 * s["access_count"])
            s["access_count"] = max(0, s["access_count"] - 1)
            if s["priority"] < 0.1:
                gone.append(k)
        for k in gone:
            del self.slots[k]
            self.evicted += 1
        return len(gone)

