def _write_subject(self):
        """Persist the working artifact into the sandbox so TEST steps and
        the terminal can actually import it (the body-of-the-agent bridge)."""
        try:
            if self.code and getattr(self, "_path", ""):
                self.filesystem.write(self._path, self.code)
                if getattr(self, "_run", ""):
                    self.filesystem.write(
                        "_rt_check.py",
                        "import sys\nsys.path.insert(0, %r)\n"
                        % str(self.filesystem.root) + self._run)
        except Exception:
            pass

def self_test(self) -> dict:
        """Does the algebra actually invert? Bind a filler to a role, unbind it,
        and measure how much of the filler survives. If this is not near 1.0,
        nothing downstream of it means anything."""
        ok = []
        for i in range(6):
            role = self.space.role(i)
            fill = self.space.of(f"__selftest_{i}")
            rec = unbind(bind(role, fill), role)
            ok.append(round(float(np.dot(rec, fill)), 4))
        return {"bind_unbind_fidelity": ok,
                "mean": round(float(np.mean(ok)), 4)}

def note_learning(self) -> None:
        """Sample the U curve from his own life: what arousal was he at, and how
        much did his synapses actually move?"""
        try:
            w = np.asarray(self.core.w, dtype=float)
        except Exception:
            return
        if self._last_w is not None and self._last_w.shape == w.shape:
            delta = float(np.mean(np.abs(w - self._last_w)))
            self.learning_samples.append(
                (self.state["arousal"], self.state["plasticity"], delta))
        self._last_w = w.copy()

def _interact_with_organ(self, pool: int, ctx_text: str):
        """Pools that mean recall are FOLLOWED: the organ is actually asked."""
        recall = {3: ("memory", "recall_episodic"),
                  4: ("memory", "recall_semantic"),
                  5: ("memory", "recall_procedural")}
        if pool not in recall:
            return None
        organ_name, what = recall[pool]
        organ = getattr(self.agent, organ_name, None)
        if organ is None:
            return None
        try:
            if what == "recall_episodic":
                seen = organ.episodic.recent(3) if hasattr(
                    organ, "episodic") else None
            elif what == "recall_semantic":
                seen = organ.semantic.search(ctx_text[:60]) if hasattr(
                    organ, "semantic") else None
            else:
                seen = (organ.procedural.best(ctx_text[:60]) if hasattr(
                    organ, "procedural") else None)
            return {"organ": organ_name, "what": what, "found": bool(seen)}
        except Exception as e:
            return {"organ": organ_name, "what": what,
                    "error": str(e)[:80]}

