                               purpose="direct")
        except NoAPIKeyError as e:
            return {"solution": "", "method": "none", "api_calls": 0,
                    "reason": str(e)}
        return {"solution": r.get("text", ""), "method": "direct_api",
                "api_calls": 1 if r.get("ok") else 0,
                "tokens": int(r.get("prompt_tokens_est", 0) or 0) +
                int(r.get("completion_tokens_est", 0) or 0),
                "verified": False,
                "mode": r.get("mode"), "reason": r.get("reason"),
                "provenance": ["direct_api(no verification available)"]}

def _is_safe_command(self, command: str) -> bool:
        """Pure policy question, answered by the fence -- not by the oracle's own
        opinion, which would be the model grading its own homework."""
        if self.sandbox is None or not str(command or "").strip():
            return False
        try:
            return bool(self.sandbox.check_command(command).get("allow"))
        except Exception:
            return False

