def _best_by_signature(rows: list[dict]) -> dict:
    """One procedure per signature: the fullest code that answers it.

    Several functions can describe the same task. Keeping the longest body is a
    crude tie-break but a defensible one -- a stub and its implementation share a
    signature, and the implementation is the one worth replaying.
    """
    best: dict[str, dict] = {}
    for r in rows:
        cur = best.get(r["signature"])
        if cur is None or r["chars"] > cur["chars"]:
            best[r["signature"]] = r
    return best

def ask(self, cue, role: int = 0, candidates=None, k: int = 1) -> dict:
        """A question put to memory, answered by unbinding.

        `candidates` defaults to every word that appears in any remembered
        proposition, so the answer is chosen from what he has actually heard
        rather than from a list supplied by the questioner.
        """
        cands = list(candidates) if candidates else sorted(
            {str(t).lower() for m in self.binder.meta for t in m["tokens"]})
        if not cands:
            return {"answer": None, "reason": "nothing remembered"}
        return self.binder.query_role(cue, int(role), cands, k=k)

def _pn_percept(self, key: str):
        """Hash a name onto real antennal-lobe projection neurons."""
        try:
            pn = np.asarray(self.engine.static.g.pn_idx, dtype=np.int64)
        except Exception:
            return None
        if pn.size == 0:
            return None
        h = hashlib.blake2b(str(key).encode("utf-8"), digest_size=32).digest()
        want = min(self.SCENT_CELLS, len(pn))
        picks = []
        for i in range(len(h) - 1):
            if len(picks) >= want:
                break
            j = int.from_bytes(h[i:i + 2], "little") % len(pn)
            if j not in picks:
                picks.append(j)
        idx = pn[np.array(picks, dtype=np.int64)]
        amp = np.array([0.55 + 0.55 * (h[(2 * k + 1) % len(h)] / 255.0)
                        for k in range(len(idx))], dtype=float)
        return idx, amp

