def list_events(self, limit: int = 20) -> list[dict]:
        """The tail of the append-only event log: what was learned, when, and on
        whose evidence. Read from disk so a restarted process still remembers."""
        out = []
        try:
            if not self.events_path.exists():
                return []
            with open(self.events_path, encoding="utf-8") as f:
                lines = f.readlines()[-max(1, int(limit)):]
            for line in lines:
                try:
                    out.append(json.loads(line))
                except Exception:
                    out.append({"kind": "unparseable", "raw": line[:200]})
        except Exception as e:
            return [{"kind": "error", "raw": str(e)[:200]}]
        return out

def reinforce(self, reward: float, v_chosen: float, v_next_max: float) -> float:
        """Apply the three-factor update from a measured reward. Returns rpe."""
        with self._lock:
            return self._reinforce_impl(reward, v_chosen, v_next_max)

def unbind(p: np.ndarray, role: np.ndarray) -> np.ndarray:
    """Approximate inverse of binding: recover the filler given the role."""
    out = np.fft.irfft(np.fft.rfft(p) * np.conj(np.fft.rfft(role)),
                       n=p.shape[0])
    n = float(np.linalg.norm(out))
    return (out / n).astype(np.float32) if n else out.astype(np.float32)

def _guard_expr(language: str, code: str) -> str:
    """'argument may be missing' written natively."""
    arg = ""
    for pat in (r"function\s+\w+\s*\(([^)]*)\)",
                r"\w+\s*\(([^)]*)\)\s*(?:\{|=>)"):
        m = re.search(pat, code or "")
        if m:
            args = [a.strip() for a in m.group(1).split(",")
                    if a.strip() and a.strip() not in ("self", "void")]
            if args:
                arg = re.sub(r"[^A-Za-z_]", "", args[0]) or ""
            break
    arg = arg or "x"
    return {"lua": f"{arg} == nil",
            "javascript": f"!{arg}",
            "c": f"!{arg}", "cpp": f"!{arg}"}.get(language, f"!{arg}")

