def normalise(text: str) -> str:
    """Case, whitespace and punctuation-insensitive, so the same question
    phrased twice does not pay twice."""
    t = re.sub(r"\s+", " ", str(text or "").strip().lower())
    return re.sub(r"[^\w ]", "", t)

