def _build_focus(self, spec) -> str:
        """The prompt the loop will keep sending: task, constraints, last three
        distinct failures, and only the files that fit."""
        if self.context_manager is None:
            return ""
        try:
            paths = self._get_relevant_files(spec)
        except Exception:
            paths = []
        if paths and self.sandbox is not None:
            files = [f for f in self.context_manager.gather_files(paths)
                     if f[1]]
        else:
            files = []
        try:
            ctx = self.context_manager.build(
                spec.get("text", ""), relevant_files=files,
                previous_attempts=self._get_previous_attempts())
            self._focus_report = ctx
            return ctx["prompt"]
        except Exception as exc:
            self._log("context", {"error": str(exc)[:120]})
            return ""

def _knowledge(self, action, target, content, language) -> dict:
        """Substrate retrieval names CONSTRUCTS; it never emits code."""
        if self.llm is None:
            return {"hint": "", "source": "none", "concepts": []}
        ask = " ".join(str(x) for x in (action, target, _plain(content),
                                        language, "pattern"))
        try:
            r = self.llm.query(ask)
        except Exception:
            return {"hint": "", "source": "error", "concepts": []}
        words = [c for c in (r.get("concepts") or [])
                 if re.fullmatch(r"[A-Za-z_:][\w:]*", str(c) or "")]
        return {"hint": ",".join(words[:3]), "source": r.get("source", ""),
                "concepts": words[:6]}

